def obj(properties):
    return {'type':'object','properties':properties,'required':list(properties),'additionalProperties':False}


def tool_definitions():
    request=deepcopy(REQUEST);definitions=request.pop('$defs')
    for k in ('$id','$schema','title','description'):request.pop(k,None)
    pin={'$ref':'#/$defs/pin'};nullable={'oneOf':[pin,{'type':'null'}]}
    sha={'type':'string','pattern':'^[0-9a-f]{64}$','maxLength':64}
    ids={'type':'array','items':{'type':'string','maxLength':64},'maxItems':32,'uniqueItems':True}
    row=obj({'task':pin,'classification':{'enum':['PRIOR_PINNED_EVIDENCE_MATCHES','MUST_RUN_FRESH']},
             'selected_manifest_sha256':sha,'selected_receipt':nullable,'supplied_receipt':nullable,
             'fresh_dependencies':ids,'fresh_ancestors':ids,
             'reasons':{'type':'array','maxItems':1024,'items':obj({'code':{'type':'string'},'subject':{'type':'string'},
                                                               'expected':nullable,'supplied':nullable})}})
    flags=('execution_performed','fresh_pass_claimed','skip_authorized','closure_verified','artifact_bytes_verified',
           'authenticity_verified','mathematical_truth_checked','proof_acceptance_changed')
    report=obj({'schema':{'const':'foundation-math-validation-receipt-report/1'},'input_sha256':sha,
                'scope':{'const':'Syntactic integrity and applicability within a caller-declared closed input boundary only.'},
                'tasks':{'type':'array','minItems':1,'maxItems':32,'items':row},**{k:{'const':False} for k in flags}})
    common={'schema_version':{'const':1},'scope':{'const':'declared_validation_evidence_planning_only'},
            **{k:{'const':False} for k in ('formal_proof','runtime_goal_acceptance','execution_performed','skip_authorized','fresh_pass_claimed')}}
    success=obj({**common,'status':{'const':'success'},'result':report})
    error=obj({**common,'status':{'const':'error'},'error':obj({k:{'type':'string'} for k in ('code','path','message')})})
    output=obj({'tool':{'const':'plan_validation_evidence'},'assessment':{'enum':['declared_validation_evidence_classified','tool_error']},
                'formal_proof':{'const':False},'runtime_goal_acceptance':{'const':False},'receipt':{'oneOf':[success,error]}})
    output['allOf']=[{'if':{'properties':{'receipt':{'properties':{'status':{'const':'success'}}}}},
                     'then':{'properties':{'assessment':{'const':'declared_validation_evidence_classified'}}},
                     'else':{'properties':{'assessment':{'const':'tool_error'}}}}]
    return [{'name':'plan_validation_evidence','readOnly':True,
             'description':'Pure classification of caller-authored task and prior-receipt pins. No file/artifact access, '
               'command execution, skipped gate, closure/authenticity/freshness certification, proof or runtime acceptance. '
               'Mandatory current-runtime/new-adapter/archival-full-replay roles remain fresh. False but coherent declarations '
               'can match; task-set completeness, role honesty and closure are external obligations. Never permission to skip. '
               'Bridge retains 65536 input bytes and existing resource guards; standalone stdin CLI has separate 262144-byte input cap.',
             'inputSchema':{'$schema':'https://json-schema.org/draft/2020-12/schema',**obj({'document':request}),'$defs':deepcopy(definitions)},
             'outputSchema':{'$schema':'https://json-schema.org/draft/2020-12/schema',**output,'$defs':deepcopy(definitions)}}]
